DEM_st.name='DEM'; 
DEM_st.lat=37.9905;
DEM_st.lon=23.8095;
DEM_st.DEM=270;
DEM_st.env='coast';
DEM_st.footp='U'; 
%%

DEM_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_DEM_Athens.nc', DEM_st.name); %[output:2afb705a]

names_rd=fieldnames(DEM_rd);
%%
datevec(DEM_rd.Time(1)) % begin in 2008 %[output:2b9fd72f]
datevec(DEM_rd.Time(end)) % end in 2025 %[output:5f7effa8]
prctile(DEM_rd.U370_S,[5 50 95]) % < 37%, ok %[output:6fbf6eea]

plotFigControl(DEM_rd,DEM_st.name); %[output:29b35919] %[output:157ff361] %[output:40ffd44a] %[output:8b2e491b] %[output:0627fc68] %[output:17125a71] %[output:4d9197f5]

%%
DEM_rd.Properties.VariableNames{6}='BsG0_S';
DEM_rd.Properties.VariableNames{7}='BsR0_S';
DEM_rd.Properties.VariableNames{2}='BbsG0_S';
DEM_rd.Properties.VariableNames{3}='BbsR0_S';
%%
% BP detection for scat coef and backscat

names_sc={'BsB0_S', 'BsG0_S', 'BsR0_S'};
break_DEM_scat_BP=change_point_analysis_Def(DEM_rd,names_sc,0.05,'DEM','scattering'); %[output:44426262] %[output:4879552b] %[output:1bffe7e6] %[output:06cbc622]
T_DEM_scat_BP=make_table_breakpoints_def(break_DEM_scat_BP); %[output:6c3ee381] %[output:2fcc2d3a] %[output:0f7ee356] %[output:8b82a87e] %[output:3d841709] %[output:49144678] %[output:9e5fc679]

names_bsc={'BbsB0_S', 'BbsG0_S', 'BbsR0_S'};
break_DEM_bscat_BP=change_point_analysis_Def(DEM_rd,names_bsc,0.05,'DEM','Backscattering'); %[output:0823a50e] %[output:9a6888c7] %[output:79d2e650] %[output:1fd22e77]
T_DEM_bscat_BP=make_table_breakpoints_def(break_DEM_bscat_BP); %[output:3d463db0]
%%
% BP detection for abs
names_abs={'Ba10_A','Ba30_A', 'Ba50_A', 'Ba70_A' };
break_DEM_abs_BP=change_point_analysis_Def(DEM_rd,names_abs,0.05,'DEM','Absorption'); %[output:22a4edae] %[output:4a2746d1] %[output:6df860a0] %[output:94447922]
T_DEM_abs_BP=make_table_breakpoints_def(break_DEM_abs_BP); %[output:2294d3d8] %[output:5280c429] %[output:920e90c0] %[output:669412f6] %[output:6b303972] %[output:80c5d700] %[output:3c4ebe54] %[output:537ef6dc] %[output:962861ef] %[output:90830131] %[output:216f7050] %[output:71dee0c7] %[output:6c33dfb5] %[output:8bd844c3] %[output:5f483ce1] %[output:3f86c38c] %[output:3075bf5e] %[output:5bb80e1e] %[output:105fe42c] %[output:4e46c513] %[output:73a1e689] %[output:659118d4] %[output:58f2a666] %[output:22fed2e8] %[output:35f3c6bf] %[output:3b363d10] %[output:941fe80d] %[output:62f21da5] %[output:71b0a39f] %[output:6b559a3b]
%%
lambdaSC=[450;550;700];
lambdaAE7=[370 470 520 590 660 880 950];
DEM_cal=compute_exp_SSA(DEM_rd,lambdaSC, lambdaAE7); %[output:0a16113e] %[output:92fa43cc] %[output:2f70e874] %[output:63834b39] %[output:0aaa4a1e] %[output:08ff6353] %[output:48433bca] %[output:2d0968c0] %[output:222ac275] %[output:2adefde9] %[output:73b7a484] %[output:25d1cc1a] %[output:0548e542] %[output:0a8caced] %[output:34ac39de] %[output:4c3656fa] %[output:87897e21] %[output:2eebf7bf] %[output:83dcf500] %[output:9ec1c33d] %[output:43489da5] %[output:4c187f79] %[output:8a4db5ea] %[output:8adf1fcb] %[output:1ae429d7] %[output:63827edb] %[output:309c2220] %[output:1f16b429] %[output:13cfad18] %[output:3ac1ee5e] %[output:7e0e67df] %[output:2f021435] %[output:18fd11ab] %[output:8b988f03] %[output:4fa9b2c6] %[output:4e97f620] %[output:6e281785] %[output:550d0d90] %[output:0fc74981] %[output:77674e89] %[output:23882651] %[output:70979edb] %[output:99bb3fbe] %[output:90ce0705] %[output:93295bc6] %[output:8b232133] %[output:3c9e0b59] %[output:526d74d1] %[output:4e5fe06b] %[output:4a801f7c] %[output:26cfa4d8] %[output:700f93a6] %[output:1b91aee9] %[output:0aae33b3] %[output:7b787d56] %[output:506caf81] %[output:4da85a3b] %[output:628e3d7f] %[output:9e92b38b] %[output:105cfd5c] %[output:7b9f3581] %[output:60a6a4e8] %[output:16a2cd18] %[output:39f2f063] %[output:68369a70] %[output:782004f1] %[output:016ce664] %[output:7a51c402] %[output:0bda8d7d] %[output:46515c1e] %[output:3e1c53fd] %[output:611f9e0b] %[output:9fcf04f7]
DEM_cal.SSAG0=DEM_rd.BsG0_S./(DEM_rd.BsG0_S+DEM_rd.Ba30_A);
plotFigControl_cal(DEM_cal, DEM_st.name); %[output:71200333] %[output:06241cfb] %[output:683fe2bc]
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg0', 'expS_br0', 'expS_gr0'};
break_DEM_exps_BP=change_point_analysis_Def(DEM_cal,names_exps,0.05,'DEM','scattering exp'); %[output:473b615b] %[output:812b9095] %[output:89a86773] %[output:106cbce4]
T_DEM_exps_BP=make_table_breakpoints_def(break_DEM_exps_BP); %[output:3a6c0920] %[output:2414d50f] %[output:5212241d] %[output:9cec64e1] %[output:17dd5010] %[output:199b0e85] %[output:05b8ba9b] %[output:38b466a1] %[output:742d3ffc] %[output:135632f7] %[output:8b4824f6] %[output:2600eeea]

names_expA={'expA_fit'};
break_DEM_expA_BP=change_point_analysis_Def(DEM_cal,names_expA,0.05,'DEM','absorption exp'); %[output:35969350] %[output:1259b1e6]
T_DEM_expA_BP=make_table_breakpoints_def(break_DEM_expA_BP); %[output:25f0de4c] %[output:02ec3b33] %[output:96e99184] %[output:0a242019] %[output:412a71ce] %[output:2b88a78e] %[output:1d9c9ac8] %[output:5bc6e785] %[output:81f01188] %[output:31b5f3ad] %[output:38741ef8]

names_BbF={'BbsFG0'};
break_DEM_BbF_BP=change_point_analysis_Def(DEM_cal,names_BbF,0.05,'DEM','backscat fraction'); %[output:776b9cce] %[output:91843dff]
T_DEM_BbF_BP=make_table_breakpoints_def(break_DEM_BbF_BP); %[output:1e4bdd18] %[output:18271c5f] %[output:78928cd9] %[output:6575d5b6] %[output:60f1e35b] %[output:06e3024f] %[output:66b8d1f9] %[output:30eb5090]

names_SSA={'SSAG0'};
break_DEM_SSA_BP=change_point_analysis_Def(DEM_cal,names_SSA,0.05,'DEM','SSA'); %[output:09076963] %[output:7679b26d]
T_DEM_SSA_BP=make_table_breakpoints_def(break_DEM_SSA_BP); %[output:0d5db759] %[output:4ea43a41] %[output:0053025a] %[output:01fcddd6] %[output:7fceddc4] %[output:96ee860c] %[output:0112751c]

%%
% FROM HERE NOT DONE, JUST COPIED
%%
DEM_tr=DEM_rd;
DEM_tr.y=year(DEM_tr.Time);
% begin at the beginning of a year: 2007 for abs, 2009 for scat
%end: 2025
P=timerange('2007-01-01','2026-01-01');
DEM_tr=DEM_tr(P,:);

% begin at the beginning of a year:  2009 for scat
Ps=timerange('2007-01-01','2009-01-01');
names=fieldnames(DEM_tr);
c=startsWith(names,["Bs";"Bbs";"U"]);
N=names(c)
for i=1:length(N)
    DEM_tr.(N{i})(Ps)=NaN;
end


DEM_cal2=compute_exp_SSA(DEM_tr,lambdaSC, lambdaAE);
DEM_cal2.SSA0=DEM_tr.BsG0_S./(DEM_tr.BsG0_S+DEM_tr.BaR_A11);
DEM_tr=outerjoin(DEM_tr, DEM_cal2);

%do not compute trend on B, R and exp with red
DEM_tr.BsB0_S=[];
DEM_tr.BsR0_S=[];
DEM_tr.BbsB0_S=[];
DEM_tr.BbsR0_S=[];

DEM_tr.expS_br0=[];
DEM_tr.expS_gr0=[];
%%
[DEM_result_MK,DEM_result_LMSlog,DEM_result_LMSlin]=all_trend_STN(DEM_tr,DEM_st);

writetable(DEM_result_MK,'DEM_res_MK.txt'); %, 'delimiter',',' )
writetable(DEM_result_LMSlog,'DEM_res_LMSlog.txt'); 
writetable(DEM_result_LMSlin,'DEM_res_LMSlin.txt'); 
plot_10y_in_two(DEM_result_MK, DEM_st,'y');

